# Let me get more detailed info with readelf for the dynamic symbols near our addresses

# For libmonosgen-2.0.so, get nearest symbols for all 4 addresses
readelf -W --dyn-syms /tmp/libmonosgen-2.0.so 2>/dev/null | grep -i "FUNC" | awk '{print $2, $3, $8}' | sort | awk -v a1=0x222098 -v a2=0x222234 -v a3=0x19bac0 -v a4=0x19bc14 '
BEGIN { addrs[1]=strtonum(a1); addrs[2]=strtonum(a2); addrs[3]=strtonum(a3); addrs[4]=strtonum(a4) }
{ 
  addr=strtonum("0x"$1); size=strtonum($2)
  for(i=1;i<=4;i++) {
    if(addrs[i] >= addr && addrs[i] < addr+size) {
      printf "0x%x -> %s+0x%x\n", addrs[i], $3, addrs[i]-addr
    }
  }
}' 2>&1

