addrs_to_find = [0x222098, 0x222234, 0x19bac0, 0x19bc14]
syms = []
with open('/tmp/mono_syms3.txt') as f:
    for line in f:
        parts = line.strip().split()
        if len(parts) >= 3:
            addr = int(parts[0], 16)
            size = int(parts[1])
            name = parts[2]
            if addr > 0:
                syms.append((addr, size, name))
syms.sort()

for target in addrs_to_find:
    # First try exact containment
    found_exact = None
    for addr, size, name in syms:
        if size > 0 and addr <= target < addr + size:
            found_exact = (addr, size, name)
            break
    if found_exact:
        offset = target - found_exact[0]
        print(f'  0x{target:x} -> {found_exact[2]}+0x{offset:x} (size=0x{found_exact[1]:x})')
    else:
        # nearest lower
        found = None
        for i in range(len(syms)-1, -1, -1):
            if syms[i][0] <= target:
                found = syms[i]
                break
        if found:
            offset = target - found[0]
            print(f'  0x{target:x} -> {found[2]}+0x{offset:x} (nearest, size=0x{found[1]:x})')
        else:
            print(f'  0x{target:x} -> ???')
"

