{"command": "# Since we can't get full debug symbols, let's work with what we have.
# The .dynsym gives us nearby exported functions. Let me get better resolution
# by finding ALL symbols near our target addresses (within reasonable range)

python3 -c "
import subprocess, re

# Parse all dynamic symbols with addresses and sizes
result = subprocess.run(['readelf', '-W', '--dyn-syms', '/tmp/libmonosgen-2.0.so'], 
                      capture_output=True, text=True)
syms = []
for line in result.stdout.split('\n'):
    parts = line.split()
    if len(parts) >= 8 and 'FUNC' in line:
        try:
            addr = int(parts[1], 16)
            size = int(parts[2])
            name = parts[7].split('@')[0]
            if addr > 0:
                syms.append((addr, size, name))
        except:
            pass

syms.sort()
addrs = [0x222098, 0x222234, 0x19bac0, 0x19bc14]

for target in addrs:
    # Find the two nearest symbols (before and after)
    prev = None
    next_s = None
    for i, (addr, size, name) in enumerate(syms):
        if addr <= target:
            prev = (addr, size, name)
        if addr > target and next_s is None:
            next_s = (addr, size, name)
            break

    print(f'0x{target:x}:')
    if prev:
        print(f'  prev: {prev[2]} @ 0x{prev[0]:x} (size={prev[1]}, ends 0x{prev[0]+prev[1]:x}, gap={target-prev[0]-prev[1]})')
    if next_s:
        print(f'  next: {next_s[2]} @ 0x{next_s[0]:x} (dist={next_s[0]-target})')
    print()
"", "description": "Analyze symbol boundaries"}
